def solve(inputs: dict) -> float:
    import numpy as np

    M = inputs['M']
    power = inputs['power']
    mod = inputs['mod']

    result = np.identity(len(M), dtype=int)
    base = np.array(M, dtype=int)

    while power > 0:
        if power % 2 == 1:
            result = (result @ base) % mod
        base = (base @ base) % mod
        power //= 2

    return int(np.sum(result))

