def solve(inputs: dict) -> float:
    n = inputs['n']
    k = inputs['k']

    def josephus(n, k):
        survivor = 0
        for i in range(1, n + 1):
            survivor = (survivor + k) % i
        return survivor + 1

    return josephus(n, k)

